#include <algorithm>
#include <array>
#include <bitset>
#include <climits>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <tuple>
#include <vector>
using namespace std;struct Pt{int x,y;bool operator<(Pt const&o)const{return tie(x,y)<tie(o.x,o.y);}bool operator==(Pt const&o)const{return x==o.x&&y==o.y;}};long long cross(Pt a,Pt b,Pt c){return 1LL*(b.x-a.x)*(c.y-a.y)-1LL*(b.y-a.y)*(c.x-a.x);}struct CI{vector<array<int,3>>c;};
int main(){int J;cin>>J;while(J--){string id;int n,budget,k;cin>>id>>n>>budget>>k;vector<Pt>all(n),cp(k);for(auto&p:all)cin>>p.x>>p.y;for(auto&p:cp)cin>>p.x>>p.y;sort(all.begin(),all.end());int extras=budget-k;vector<int>xs,ys;map<Pt,int>orig;for(int i=0;i<n;i++){xs.push_back(all[i].x);ys.push_back(all[i].y);orig[all[i]]=i;}sort(xs.begin(),xs.end());xs.erase(unique(xs.begin(),xs.end()),xs.end());sort(ys.begin(),ys.end());ys.erase(unique(ys.begin(),ys.end()),ys.end());auto cid=[&](int x,int y){return x*ys.size()+y;};vector<vector<pair<unsigned char,unsigned char>>>edges(xs.size()*ys.size());for(int x=0;x<(int)xs.size();x++)for(int y=0;y<(int)ys.size();y++){Pt p{xs[x],ys[y]};for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)if(cross(all[a],all[b],p)==0)edges[cid(x,y)].push_back({a,b});}vector<int>core;bitset<192>cm;for(auto p:cp){int v=orig[p];core.push_back(v);cm[v]=1;}sort(core.begin(),core.end());vector<CI>info(edges.size());for(int z=0;z<(int)edges.size();z++){Pt p{xs[z/ys.size()],ys[z%ys.size()]};vector<pair<int,int>>rem;for(auto [aa,bb]:edges[z])if(!cm[aa]&&!cm[bb])rem.push_back({aa,bb});set<vector<int>>sol;vector<int>ch;auto it=orig.find(p);if(it!=orig.end()&&!cm[it->second])ch.push_back(it->second);function<void()>go=[&](){if((int)ch.size()>extras)return;int a=-1,b=-1;for(auto e:rem)if(find(ch.begin(),ch.end(),e.first)==ch.end()&&find(ch.begin(),ch.end(),e.second)==ch.end()){a=e.first;b=e.second;break;}if(a<0){auto s=ch;sort(s.begin(),s.end());sol.insert(s);return;}for(int v:{a,b})if(find(ch.begin(),ch.end(),v)==ch.end())ch.push_back(v),go(),ch.pop_back();};go();vector<vector<int>>vv(sol.begin(),sol.end());for(auto&s:vv){bool m=1;for(auto&t:vv)if(t.size()<s.size()&&includes(s.begin(),s.end(),t.begin(),t.end()))m=0;if(m){array<int,3>a{-1,-1,-1};for(int i=0;i<(int)s.size();i++)a[i]=s[i];info[z].c.push_back(a);}}}vector<int>av;for(int i=0;i<n;i++)if(!cm[i])av.push_back(i);bool found=0;unsigned long long subsets=0,nodes=0;vector<int>ce,FD;vector<Pt>FA;auto valid=[&](int z,bitset<192>const&e){for(auto a:info[z].c){bool ok=1;for(int i=0;i<3&&a[i]>=0;i++)if(!e[a[i]])ok=0;if(ok)return true;}return false;};function<void(int,int)>choose=[&](int st,int left){if(found)return;if(left){for(int i=st;i<=(int)av.size()-left&&!found;i++)ce.push_back(av[i]),choose(i+1,left-1),ce.pop_back();return;}subsets++;vector<int>D=core;D.insert(D.end(),ce.begin(),ce.end());sort(D.begin(),D.end());bitset<192>dm,em;for(int v:D)dm[v]=1;for(int v:ce)em[v]=1;vector<int>rx,cy;for(int v:D)rx.push_back(all[v].x),cy.push_back(all[v].y);sort(rx.begin(),rx.end());sort(cy.begin(),cy.end());int B=D.size();vector<vector<int>>op(B);for(int r=0;r<B;r++)for(int c=0;c<B;c++){int x=lower_bound(xs.begin(),xs.end(),rx[r])-xs.begin(),y=lower_bound(ys.begin(),ys.end(),cy[c])-ys.begin();if(valid(cid(x,y),em))op[r].push_back(c);}for(auto&o:op)if(o.empty())return;vector<Pt>A;vector<int>used(B);set<Pt>as;function<void(int)>assign=[&](int r){if(found)return;nodes++;if(r==B){auto s=A;sort(s.begin(),s.end());vector<Pt>old;for(int v:D)old.push_back(all[v]);sort(old.begin(),old.end());if(s==old)return;found=1;FD=D;FA=s;return;}int last=INT_MIN;for(int c:op[r])if(!used[c]){if(cy[c]==last)continue;last=cy[c];Pt p{rx[r],cy[c]};if(as.count(p))continue;bool ok=1;for(auto q:A){for(int v=0;v<n;v++)if(!dm[v]&&cross(q,p,all[v])==0){ok=0;break;}if(!ok)break;}for(int i=0;i<(int)A.size()&&ok;i++)for(int j=i+1;j<(int)A.size();j++)if(cross(A[i],A[j],p)==0)ok=0;if(!ok)continue;used[c]=1;A.push_back(p);as.insert(p);assign(r+1);as.erase(p);A.pop_back();used[c]=0;}};assign(0);};choose(0,extras);cout<<"RES "<<id<<" "<<found<<" "<<subsets<<" "<<nodes<<"\n";if(found){cout<<"D";for(int v:FD)cout<<" "<<all[v].x<<","<<all[v].y;cout<<"\nA";for(auto p:FA)cout<<" "<<p.x<<","<<p.y;cout<<"\n";}}}
